import { useSearchParams, useNavigate } from "react-router-dom";
import { useState, useEffect } from "react";
import { useForm } from "react-hook-form";
import { toast } from "sonner";
import "./ResetearContrasenia.css";
import vino from "../../../assets/vino_reseteo.png";
import cerveza from "../../../assets/cerveza_reseteo.png";

export default function ResetearContrasenia({
    tokenProp = null,
    correoProp = null,
    modo = "reseteo", // "reseteo" | "cambio"
    onCerrar
}) {
    const [params] = useSearchParams();
    const navegarHacia = useNavigate();

    // Usar props si vienen, sino usar parámetros de URL
    const token = tokenProp || params.get("token");
    const correo = correoProp || params.get("email");

    const [cargando, setCargando] = useState(false);

    const { register, handleSubmit, watch, formState: { errors } } = useForm();

    // 👉 Fondo SOLO en esta pantalla cuando es modo reseteo
    useEffect(() => {
        if (modo === "reseteo") {
            document.body.classList.add("__reset_fondo");
            return () => document.body.classList.remove("__reset_fondo");
        }
    }, [modo]);

    const onSubmit = async (data) => {
        setCargando(true);

        try {
            let url, body;

            if (modo === "reseteo") {
                // Modo reseteo (desde correo)
                url = `${import.meta.env.VITE_API_BASE_URL}/api/usuario/reset`;
                body = {
                    correo,
                    token,
                    contraseña: data.contraseña,
                };
            } else {
                // Modo cambio (desde perfil con sesión iniciada)
                url = `${import.meta.env.VITE_API_BASE_URL}/api/usuario/cambiar-contrasenia`;
                body = {
                    correo,
                    contraseña_actual: data.contraseña_actual,
                    nueva_contraseña: data.nueva_contraseña,
                };
            }

            const resp = await fetch(url, {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    ...(modo === "cambio" && { "Authorization": `Bearer ${token}` })
                },
                body: JSON.stringify(body),
            });

            const resultado = await resp.json();

            if (resp.ok) {
                const mensaje = modo === "reseteo"
                    ? "Contraseña restablecida con éxito."
                    : "Contraseña cambiada con éxito.";

                toast.success(mensaje, {
                    className: "__toaster_success",
                });

                if (modo === "reseteo") {
                    setTimeout(() => {
                        navegarHacia("/inicioSesion");
                    }, 1500);
                }
                else{
                    onCerrar();
                }


            } else {
                toast.error(resultado.message || "Error al procesar la solicitud.", {
                    className: "__toaster_error",
                });
            }
        } catch (error) {
            console.error(error);
            toast.error("Error de conexión con el servidor.", {
                className: "__toaster_error",
            });
        } finally {
            setCargando(false);
        }
    };

    // Solo validar token/correo en modo reseteo
    if (modo === "reseteo" && (!token || !correo)) {
        return (
            <div className="__reset_card">
                <h2 className="__reset_title">Enlace inválido</h2>
                <p className="__reset_text">Este enlace ha expirado o no es válido.</p>
                <div className="__reset_footer">
                    <a href="/inicioSesion" className="__reset_link">Volver al inicio</a>
                </div>
            </div>
        );
    }

    return (
        <>
            {cargando && (
                <div className="__reset_loader_fondo">
                    <div className="__reset_loader"></div>
                </div>
            )}

            <div className={`__reset_card ${modo === "cambio" ? "__cambio_modo" : ""}`}>
                <div className="__reset_header">
                    <img src={vino} className="__reset_img_left" alt="Vino" />
                    <h2 className="__reset_title">
                        {modo === "reseteo" ? "Restablecer Contraseña" : "Cambiar Contraseña"}
                    </h2>
                    <img src={cerveza} className="__reset_img_right" alt="Cerveza" />
                </div>

                <form onSubmit={handleSubmit(onSubmit)} className="__reset_form">
                    {modo === "cambio" && (
                        <>
                            <div className="__reset_input_box">
                                <input
                                    type="password"
                                    {...register("contraseña_actual", {
                                        required: "Ingrese su contraseña actual",
                                    })}
                                />
                                <label>Contraseña actual</label>
                                <span></span>
                            </div>
                            {errors.contraseña_actual && <p className="__reset_error">{errors.contraseña_actual.message}</p>}
                        </>
                    )}

                    <div className="__reset_input_box">
                        <input
                            type="password"
                            {...register(modo === "reseteo" ? "contraseña" : "nueva_contraseña", {
                                required: "Ingrese su nueva contraseña",
                                minLength: {
                                    value: 6,
                                    message: "Debe tener al menos 6 caracteres",
                                },
                            })}
                        />
                        <label>{modo === "reseteo" ? "Nueva contraseña" : "Nueva contraseña"}</label>
                        <span></span>
                    </div>
                    {errors.contraseña && <p className="__reset_error">{errors.contraseña?.message}</p>}
                    {errors.nueva_contraseña && <p className="__reset_error">{errors.nueva_contraseña?.message}</p>}

                    <div className="__reset_input_box">
                        <input
                            type="password"
                            {...register("confirmar", {
                                required: "Confirme su contraseña",
                                validate: (v) => {
                                    const password = watch(modo === "reseteo" ? "contraseña" : "nueva_contraseña");
                                    return v === password || "Las contraseñas no coinciden";
                                },
                            })}
                        />
                        <label>Confirmar contraseña</label>
                        <span></span>
                    </div>
                    {errors.confirmar && <p className="__reset_error">{errors.confirmar.message}</p>}

                    <input
                        type="submit"
                        value={modo === "reseteo" ? "Restablecer" : "Cambiar Contraseña"}
                        className="__reset_btn"
                        disabled={cargando}
                    />
                </form>

                <div className="__reset_footer">
                    <a href={modo === "reseteo" ? "/inicioSesion" : "/perfil"} className="__reset_link">
                        {modo === "reseteo" ? "Volver al inicio" : "Volver al perfil"}
                    </a>
                </div>
            </div>
        </>
    );
}